import { useEffect, useState } from "react";

import type { Deck } from "./deck";
import { getDeck } from "./deck-repository";

export type DeckLoadStatus = "loading" | "not-found" | "error" | "ready";

export type UseDeckByRouteParamResult = {
  /** Defined only once `status` is `"ready"`. */
  deck: Deck | undefined;
  status: DeckLoadStatus;
};

/**
 * Loads the deck a route's `deckId` parameter names, already normalized by
 * `normalizeDeckId` at the call site. Every screen under `/decks/[deckId]`
 * needs the same lookup around it — a cancelled-fetch guard so a slow
 * response cannot land after the screen has moved on, a `"not-found"` status
 * for both a malformed id and one that matches nothing in the store, and an
 * `"error"` status for a lookup that rejected outright — so this is where
 * that lookup lives instead of being copied at each call site.
 */
export function useDeckByRouteParam(
  deckId: string | null,
): UseDeckByRouteParamResult {
  const [deck, setDeck] = useState<Deck | null | undefined>(undefined);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    if (deckId === null) {
      return;
    }

    let cancelled = false;
    getDeck(deckId)
      .then((found) => {
        if (!cancelled) setDeck(found ?? null);
      })
      .catch(() => {
        if (!cancelled) setFailed(true);
      });
    return () => {
      cancelled = true;
    };
  }, [deckId]);

  if (deckId === null || deck === null) {
    return { deck: undefined, status: "not-found" };
  }
  if (failed) {
    return { deck: undefined, status: "error" };
  }
  if (deck === undefined) {
    return { deck: undefined, status: "loading" };
  }
  return { deck, status: "ready" };
}

import type { ExpoConfig } from "expo/config";

const config: ExpoConfig = {
  name: "Recall",
  slug: "recall",
  scheme: "recall",
  version: "1.0.0",
  orientation: "portrait",
  userInterfaceStyle: "automatic",
  ios: { supportsTablet: true, bundleIdentifier: "dev.axross.recall" },
  android: { package: "dev.axross.recall" },
  plugins: [
    "expo-router",
    [
      "expo-camera",
      {
        cameraPermission:
          "Recall uses the camera to photograph what a card is about.",
      },
    ],
  ],
};

export default config;

